  "codebook": {
    "definition": "Credit-claiming is defined as any statement in which a senator asserts personal or collaborative responsibility for bringing about a positive, tangible government action, policy decision, or financial benefit (such as grants, appropriations, projects, or passed legislation) that benefits their constituents or the nation as a whole.",
    "clarification": "To classify a text as credit-claiming (1), look for specific linguistic indicators that connect the senator's actions to a positive outcome. This includes claims of: (a) authoring, co-sponsoring, or passing specific bills or amendments; (b) securing, helping to secure, or announcing federal grants, projects, or appropriations for their home state; and (c) actively intervening with executive agencies (e.g., writing letters or holding oversight hearings) that successfully resulted in a direct change in agency policy. Announcing a federal grant to the home state is treated as credit-claiming even if the senator's active role is not fully detailed, as it associates the senator with the positive outcome.",
    "positive_examples": [
      {
        "document_id": "1862",
        "explanation": "The senators explicitly claim that they 'have delivered on their promise to secure federal funding' for vital military projects in Butte, Montana."
      },
      {
        "document_id": "1257",
        "explanation": "Senator DeWine claims direct responsibility for the grant awarded to the Parma Fire Department, highlighting that it is part of 'his Firefighter Investment and Response Enhancement (FIRE) Act' which he 'wrote and passed in 2000.'"
      }
    ],
    "negative_clarification": "Do NOT classify a text as credit-claiming (0) if the senator is merely: (a) stating a policy position, vote intention, or ideological view (position-taking); (b) criticizing the opposing party or the executive branch without claiming credit for a successful outcome; (c) calling for or proposing actions that have not yet occurred (advocacy/urging action); (d) performing routine administrative, commemorative, or symbolic acts (such as honoring a deceased colleague or hosting a town hall); or (e) thanking or praising another entity for an outcome without claiming a personal role in achieving it.",
    "negative_examples": [
      {
        "document_id": "656",
        "explanation": "Senator Kerry's statement is entirely a critique of the Bush Administration's incompetence regarding port security. He does not claim credit for any personal legislative or funding achievements."
      },
      {
        "document_id": "918",
        "explanation": "This document is a simple informational announcement inviting citizens to a local town meeting. It contains no policy achievements, funding announcements, or legislative credit-claiming."
      }
    ]
  }
}
